<template><section class="application-panel review-workflow"><div class="panel-heading"><div><p class="application-eyebrow">Review participation</p><h2>Independent reviews</h2></div><strong>{{ progressLabel }}</strong></div><p class="panel-note">Exactly three scored reviews maximum. Existing scores stay hidden until Admin explicitly reveals them.</p>
  <div class="reviewer-action-bar"><template v-if="ownSlot"><p>My review: <strong>{{ ownSlot.reviewLabel }} · {{ stateLabel(ownSlot.state) }}</strong></p><RouterLink class="application-action-link" :to="reviewRoute">Start or continue my review</RouterLink></template><template v-else><p>{{ identity.role === 'admin' ? 'Admin may occupy one normal review slot.' : 'You have not claimed this application.' }}</p><button v-if="availableSlots" type="button" @click="claim">{{ identity.role === 'admin' ? 'Review application independently' : 'Claim review' }}</button></template><button v-if="ownSlot?.state === 'claimed'" type="button" class="danger-muted" @click="release(ownSlot)">Release my claim</button></div>
  <div class="workflow-indicators"><span>{{ claimedCount }} claimed</span><span>{{ application.completedReviews }} completed</span><span>{{ concernCount ? `${concernCount} serious concern${concernCount > 1 ? 's' : ''}` : 'No submitted serious concerns' }}</span><span>{{ earlyEligible ? 'Eligible for early acceptance' : 'Not eligible for early acceptance' }}</span></div>
  <div class="reviewer-grid"><article v-for="slot in visibleSlots" :key="slot.slot" class="reviewer-card"><span>Reviewer {{ slot.slot }}</span><strong>{{ slotName(slot) }}</strong><small>{{ stateLabel(slot.state) }}</small><small v-if="slot.claimedAt">Claimed {{ formatDate(slot.claimedAt) }}</small><small v-if="slot.submittedAt">Submitted {{ formatDate(slot.submittedAt) }}</small><strong v-if="canSeeReview(slot) && slot.percentage !== null">{{ slot.reviewLabel }} · {{ Math.round(slot.percentage) }}%</strong><p v-if="canSeeReview(slot) && slot.seriousConcern" class="concern-warning"><strong>Serious concern</strong><span>{{ slot.concernExplanation }}</span></p><button v-if="identity.role === 'admin' && ['claimed','in-progress'].includes(slot.state)" type="button" class="danger-muted" @click="release(slot)">Release slot</button><details v-if="canSeeReview(slot) && slot.state === 'submitted'"><summary>View submitted review analysis</summary><section class="admin-eligibility-analysis"><h4>Eligibility checks</h4><div v-for="check in eligibilityChecks" :key="check.id"><strong>{{ check.label }}</strong><span>{{ eligibilityLabel(slot.eligibility[check.id]) }}</span><p v-if="slot.eligibilityExplanations[check.id]">{{ slot.eligibilityExplanations[check.id] }}</p></div></section><div v-for="criterion in criteria" :key="criterion.id" class="review-summary-item"><strong>{{ criterion.label }} — {{ slot.scores[criterion.id] }}/10</strong><span>Internal weight {{ criterion.weight }}% · contribution {{ contribution(slot, criterion) }} points</span><p>{{ slot.comments[criterion.id] || 'No explanation provided' }}</p></div><section><h4>Overall assessment</h4><p>{{ slot.overallAssessment || 'No overall assessment provided' }}</p></section></details></article></div>
  <div v-if="identity.role === 'admin' && completedSlots.length && !application.adminReviewsRevealed" class="reveal-warning"><p>Completed review detail is hidden to protect independent assessment.</p><button type="button" @click="reveal">View completed reviews</button></div>
  <div v-if="application.finalPercentage !== null" class="outcome-card"><strong>Final combined average: {{ Math.round(application.finalPercentage) }}%</strong><p>{{ outcomeLabel }}</p><small>Decision uses the full unrounded average.</small></div>
  <section v-if="identity.role === 'admin'" class="admin-demo-controls"><h3>Administrative actions</h3><button v-if="canProgress" type="button" @click="openAction('bypass')">{{ application.status === 'automatically-declined' ? 'Override rejection and progress to induction' : application.status === 'admin-response-required' ? 'Progress to induction after concern review' : 'Bypass reviews and progress to induction' }}</button><button v-if="application.status === 'accepted-induction'" type="button" @click="openAction('pause')">Pause induction and return to admin review</button><button v-if="application.status === 'induction-paused'" type="button" @click="openAction('restore')">Restore induction progression</button><button v-if="['awaiting-admin-decision','admin-response-required','induction-paused'].includes(application.status)" type="button" class="danger-muted" @click="decline">Decline application</button><RouterLink class="application-action-link" :to="{ name: 'AdminInductions' }">Open induction schedule</RouterLink></section>
  <p v-if="application.successMessage" class="workflow-success" role="status">{{ application.successMessage }}</p>
  <section v-if="identity.role === 'admin' && application.emailPreview" class="email-preview"><span class="demo-data-badge">Email would be sent</span><h3>{{ application.emailPreview.subject }}</h3><p>{{ application.emailPreview.body }}</p></section>
  <section v-if="identity.role === 'admin'" class="audit-timeline"><h3>Demo audit timeline</h3><ol><li v-for="event in [...application.auditEvents].reverse()" :key="event.id"><strong>{{ event.action }}</strong><span>{{ event.actor }} · {{ formatDate(event.timestamp) }}</span><p>{{ event.summary }}</p></li></ol></section>
  <DemoActionModal :open="Boolean(action)" :title="modalCopy.title" :description="modalCopy.description" :warning="modalCopy.warning" :confirm-label="modalCopy.confirm" @cancel="action=''" @confirm="confirmAction" />
</section></template>
<script>
import DemoActionModal from './DemoActionModal.vue'; import { CREATOR_PROGRAMME_CRITERIA, ELIGIBILITY_CHECKS, acceptEarly, adminBypass, adminDecline, claimReview, demoWorkflow, getDemoIdentity, isEarlyAcceptanceEligible, pauseInduction, releaseReview, restoreInduction, revealCompletedReviews } from '../applicationAdminData.js';
export default { name: 'ReviewWorkflowPanel', components: { DemoActionModal }, props: { application: { type: Object, required: true } }, data: () => ({ workflow: demoWorkflow, criteria: CREATOR_PROGRAMME_CRITERIA, eligibilityChecks: ELIGIBILITY_CHECKS, action: '' }), computed: { identity() { this.workflow.revision; return getDemoIdentity(); }, ownSlot() { return this.application.reviewerSlots.find((slot) => slot.reviewerId === this.identity.id); }, reviewRoute() { return { name: 'AdminApplicationReview', params: { applicationId: this.application.id } }; }, availableSlots() { return this.application.reviewerSlots.some((slot) => slot.state === 'available'); }, claimedCount() { return this.application.reviewerSlots.filter((slot) => !['available','closed'].includes(slot.state)).length; }, completedSlots() { return this.application.reviewerSlots.filter((slot) => slot.state === 'submitted'); }, concernCount() { return this.completedSlots.filter((slot) => slot.seriousConcern).length; }, earlyEligible() { this.workflow.revision; return isEarlyAcceptanceEligible(); }, progressLabel() { return this.application.completedReviews === 3 ? '3 of 3 reviews completed' : `${this.claimedCount} of 3 claimed · ${this.application.completedReviews} completed`; }, visibleSlots() { return this.identity.role === 'admin' ? this.application.reviewerSlots : this.application.reviewerSlots.map((slot) => slot.reviewerId === this.identity.id ? slot : { slot: slot.slot, state: slot.state === 'available' ? 'available' : 'claimed-private' }); }, canProgress() { return ['awaiting-review','under-review','awaiting-admin-decision','admin-response-required','automatically-declined'].includes(this.application.status); }, outcomeLabel() { return { 'qualified-induction': 'Automatically qualified for induction', 'admin-decision': 'Admin decision required', 'automatic-decline': 'Automatically declined', 'admin-response-required': 'Admin response required because a concern or eligibility issue overrides automatic acceptance' }[this.application.outcome] || ''; }, modalCopy() { return { early: { title: 'Accept early and progress to induction', description: 'This admin decision waives the third review.', warning: 'Any unfinished third claim and draft will be closed. Submitted reviews are preserved.', confirm: 'Accept early' }, bypass: { title: this.application.status === 'automatically-declined' ? 'Override rejection and progress to induction' : 'Bypass reviews and progress to induction', description: 'The normal review process will be overridden.', warning: 'Active unfinished claims and drafts will close. Submitted reviews and the original outcome remain preserved.', confirm: 'Progress to induction' }, pause: { title: 'Pause induction and return to admin review', description: 'The simulated invitation will be revoked and new booking prevented.', warning: 'Any existing simulated booking would be paused or cancelled.', confirm: 'Pause induction' }, restore: { title: 'Restore induction progression', description: 'A new simulated invitation and applicant-safe email preview will be prepared.', warning: 'This is an explicit administrative decision.', confirm: 'Restore induction' } }[this.action] || {}; } }, methods: { openAction(action) { this.action = action; }, async confirmAction(reason) { if (this.action === 'early') acceptEarly(reason); else if (this.action === 'pause') pauseInduction(reason); else if (this.action === 'restore') restoreInduction(reason); else adminBypass(reason, this.application.status === 'automatically-declined'); this.action = ''; }, claim() { if (window.confirm('Claim one of three independent review slots?')) claimReview(); }, release(slot) { if (window.confirm(slot.state === 'in-progress' ? 'Discard this unsubmitted draft and release the slot?' : 'Release this claim?')) releaseReview(slot.slot); }, reveal() { if (window.confirm('Viewing existing reviews may influence your independent assessment. Continue and permanently mark any later admin review as informed?')) revealCompletedReviews(); }, decline() { const reason = window.prompt('Applicant-facing decline reason (required).'); if (reason?.trim()) adminDecline(reason, window.prompt('Optional reapplication guidance:') || ''); }, canSeeReview(slot) { return this.identity.role === 'admin' && slot.state === 'submitted' && (this.application.adminReviewsRevealed || slot.reviewerId === this.identity.id); }, contribution(slot, criterion) { return ((slot.scores[criterion.id] / 10) * criterion.weight).toFixed(2); }, eligibilityLabel(value) { return ({ meets: 'Meets requirement', clarification: 'Needs clarification', 'does-not-meet': 'Does not meet requirement' })[value] || 'Not recorded'; }, slotName(slot) { if (this.identity.role !== 'admin' && slot.state === 'claimed-private') return 'Claimed by another reviewer'; return slot.reviewerName || (slot.state === 'closed' ? 'Closed' : 'Not assigned'); }, stateLabel(value) { return ({ available: 'Not assigned', claimed: 'Not started', 'claimed-private': 'Unavailable', 'in-progress': 'In progress', submitted: 'Submitted', closed: 'Closed' })[value] || value; }, formatDate(value) { return new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)); } } };
</script>
